function triggerClutch(tg){
  if(reduceMotion || !CFG.clutch) return;
  if(state.t - _clutchLast < CFG.clutchCooldown) return;       // keep each flourish a treat, not a strobe
  _clutchLast=state.t;
  clutchT=clutchDur=CFG.clutchTime;                            // camera FOV punch timer (read in the camera block of animate)
  ensureClutchRing(); _clutchRingPos.copy(tg.mesh.position); clutchRingT=clutchRingDur=CFG.clutchRingTime;   // expanding shockwave ring at the impact
}
function killTarget(tg, clutch){
  dropTarget(tg);
  if(clutch) explodeAt(tg.mesh.position, tg.radius*CFG.clutchBurst, CLUTCH_COLOR, CFG.clutchSlow);
  else if(tg.hpMax>1) explodeAt(tg.mesh.position, tg.radius*1.55, TANK_COLOR, 0.55);   // tank finale: bigger amber burst + brief local slow (juice; still rhythm-safe — only the explosion ages slow)
  else explodeAt(tg.mesh.position, tg.radius, KIND_COLOR[tg.kind||0]);
  removeTarget(tg);
}

